<script lang="ts">
	import { onMount } from 'svelte';
	import { api, type RecordValue } from '$lib/api';
	import EmptyState from '$lib/EmptyState.svelte';

	export let onuse: ((entry: RecordValue) => void) | undefined;
	export let onfailure: ((message: string) => void) | undefined;
	type Bundle = { familyId: string; name: string; versions: RecordValue[] };
	const asRecord = (value: unknown): RecordValue => value && typeof value === 'object' ? value as RecordValue : {};
	const asRecords = (value: unknown): RecordValue[] => Array.isArray(value) ? value as RecordValue[] : [];
	const display = (value: unknown) => value === null || value === undefined || value === '' ? '—' : String(value);
	const number = (value: unknown) => Number.isFinite(Number(value)) ? Number(value) : 0;

	let entries: RecordValue[] = [], selectedId = '', selectedIds: string[] = [], detail: RecordValue | null = null, previews: RecordValue[] = [];
	let query = '', label = '', page = 0, loading = true, loadingDetail = false, scanning = false, freezing = false;
	let unavailable = '', detailError = '', comparison: RecordValue | null = null, comparisonError = '';
	const current = () => entries.find((entry) => String(entry.catalog_id) === selectedId);
	const entryStatus = (entry: RecordValue) => String(entry.status ?? 'working');
	const familyId = (entry: RecordValue) => String(entry.family_id ?? entry.training_set_family ?? entry.catalog_id);
	const familyName = (entry: RecordValue) => display(entry.training_set_family ?? entry.name);
	const classes = () => asRecords(detail?.classes ?? asRecord(detail?.entry).classes ?? current()?.classes);
	const previewUrl = (sample: RecordValue) => String(sample.preview_url ?? sample.image_url ?? '');
	const versionEntries = () => current() ? entries.filter((entry) => familyId(entry) === familyId(current()!)).sort((a, b) => display(b.modified_at).localeCompare(display(a.modified_at))) : [];
	const matches = (entry: RecordValue) => [entry.name, entry.training_set_family, entry.training_set_version, entry.relative_path, entry.dataset_id, ...asRecords(entry.classes).map((item) => item.name)].join(' ').toLowerCase().includes(query.toLowerCase());
	function bundles(status: 'frozen' | 'unfrozen'): Bundle[] {
		const grouped = new Map<string, Bundle>();
		for (const entry of entries.filter((entry) => matches(entry) && (status === 'frozen' ? entryStatus(entry) === 'frozen' : entryStatus(entry) !== 'frozen'))) {
			const key = familyId(entry), bundle = grouped.get(key) ?? { familyId: key, name: familyName(entry), versions: [] }; bundle.versions.push(entry); grouped.set(key, bundle);
		}
		return [...grouped.values()].map((bundle) => ({ ...bundle, versions: bundle.versions.sort((a, b) => display(b.modified_at).localeCompare(display(a.modified_at))) })).sort((a, b) => a.name.localeCompare(b.name));
	}
	const itemCount = (bundle: Bundle) => number(bundle.versions[0]?.item_count);
	const classCount = (bundle: Bundle) => number(bundle.versions[0]?.class_count);

	async function load(selectFirst = true) {
		loading = true; unavailable = '';
		try { entries = asRecords((await api.trainingCatalogEntries()).entries); if (selectFirst && (!selectedId || !current()) && entries.length) await select(String(entries.find((entry) => entryStatus(entry) === 'frozen')?.catalog_id ?? entries[0].catalog_id)); }
		catch (error) { unavailable = error instanceof Error ? error.message : 'The training-set catalog is unavailable.'; onfailure?.(unavailable); }
		finally { loading = false; }
	}
	async function scan() { scanning = true; try { await api.scanTrainingCatalog({}); await load(); } catch (error) { unavailable = error instanceof Error ? error.message : 'Could not scan Oracle SQLite training sets.'; onfailure?.(unavailable); } finally { scanning = false; } }
	async function select(id: string) {
		selectedId = id; detail = null; previews = []; detailError = ''; page = 0; label = ''; loadingDetail = true;
		try { const [nextDetail, previewResult] = await Promise.all([api.trainingCatalogDetail(id), api.trainingCatalogPreviews(id, { limit: 18 })]); if (selectedId !== id) return; detail = nextDetail; previews = asRecords(previewResult.items); }
		catch (error) { if (selectedId === id) detailError = error instanceof Error ? error.message : 'Catalog details are not available.'; }
		finally { if (selectedId === id) loadingDetail = false; }
	}
	async function loadPreviews() { if (!selectedId) return; try { previews = asRecords((await api.trainingCatalogPreviews(selectedId, { label, offset: page * 18, limit: 18 })).items); } catch (error) { detailError = error instanceof Error ? error.message : 'Sample previews are not available.'; } }
	async function freeze() { if (!current() || entryStatus(current()!) === 'frozen') return; freezing = true; detailError = ''; try { await api.freezeTrainingCatalogEntry(selectedId); await load(false); await select(selectedId); } catch (error) { detailError = error instanceof Error ? error.message : 'Could not freeze this training-set revision.'; } finally { freezing = false; } }
	function toggle(id: string) { selectedIds = selectedIds.includes(id) ? selectedIds.filter((value) => value !== id) : [...selectedIds, id]; comparison = null; comparisonError = ''; }
	async function compare() { try { comparison = await api.trainingCatalogComparison(selectedIds); } catch (error) { comparisonError = error instanceof Error ? error.message : 'The selected revisions could not be compared.'; } }
	function setLabel(value: string) { label = value; page = 0; void loadPreviews(); }
	function movePage(delta: number) { page = Math.max(0, page + delta); void loadPreviews(); }
	onMount(() => { void load(); });
</script>

<section class="catalog-intro"><div><p class="eyebrow">TRAINING SET CATALOG</p><h1>Versioned Oracle SQLite training sets.</h1><p>Only Oracle Builder dataset revisions are cataloged. Image folders must be converted before they become training evidence.</p></div><button on:click={scan} disabled={scanning}>{scanning ? 'Scanning…' : 'Scan datasets'}</button></section>

{#if unavailable}<section class="catalog-unavailable" role="status"><strong>Catalog service unavailable</strong><p>{unavailable}</p><button class="secondary small" on:click={() => load()}>Try again</button></section>
{:else if loading}<section class="panel"><p class="empty">Loading Oracle SQLite training sets…</p></section>
{:else if !entries.length}<section class="panel"><EmptyState title="No Oracle training sets discovered" text="Place Oracle Builder SQLite datasets in datasets/ or convert image folders explicitly before cataloging." action="Scan datasets" onaction={scan} /></section>
{:else}
	<section class="catalog-toolbar panel"><label>Find a family or revision<input bind:value={query} placeholder="ISIISNet, version, class…" /></label><div class="selection-actions"><span>{selectedIds.length} revisions selected</span><button class="secondary" disabled={selectedIds.length < 2} on:click={compare}>Compare revisions</button></div></section>
	<div class="catalog-layout"><div class="catalog-tables">
		<section class="catalog-table panel" aria-label="Frozen training sets"><header><div><p class="eyebrow">READY FOR TRAINING</p><h2>Frozen training sets</h2></div><span class="count">{bundles('frozen').length}</span></header><div class="catalog-row catalog-head"><span></span><span>Training-set family</span><span>Versions</span><span>Images</span><span>Classes</span><span>Lifecycle</span></div>{#each bundles('frozen') as bundle}<div class:active={familyId(current() ?? {}) === bundle.familyId} class="catalog-row"><label class="check"><input type="checkbox" checked={selectedIds.includes(String(bundle.versions[0].catalog_id))} on:change={() => toggle(String(bundle.versions[0].catalog_id))} aria-label={`Select ${bundle.name}`} /></label><button class="catalog-name" on:click={() => select(String(bundle.versions[0].catalog_id))}><strong>{bundle.name}</strong><small>{display(bundle.versions[0].training_set_version)} · latest revision</small></button><span>{bundle.versions.length}</span><span>{itemCount(bundle).toLocaleString()}</span><span>{classCount(bundle).toLocaleString()}</span><span class="status frozen">Frozen</span></div>{/each}{#if !bundles('frozen').length}<p class="empty table-empty">No frozen revisions match this search.</p>{/if}</section>
		<section class="catalog-table panel" aria-label="Working training sets"><header><div><p class="eyebrow">NOT YET TRAINABLE</p><h2>Unfrozen training sets</h2></div><span class="count">{bundles('unfrozen').length}</span></header><div class="catalog-row catalog-head"><span></span><span>Training-set family</span><span>Versions</span><span>Images</span><span>Classes</span><span>Lifecycle</span></div>{#each bundles('unfrozen') as bundle}<div class:active={familyId(current() ?? {}) === bundle.familyId} class="catalog-row"><label class="check"><input type="checkbox" checked={selectedIds.includes(String(bundle.versions[0].catalog_id))} on:change={() => toggle(String(bundle.versions[0].catalog_id))} aria-label={`Select ${bundle.name}`} /></label><button class="catalog-name" on:click={() => select(String(bundle.versions[0].catalog_id))}><strong>{bundle.name}</strong><small>{display(bundle.versions[0].training_set_version)} · latest revision</small></button><span>{bundle.versions.length}</span><span>{itemCount(bundle).toLocaleString()}</span><span>{classCount(bundle).toLocaleString()}</span><span class="status working">Working</span></div>{/each}{#if !bundles('unfrozen').length}<p class="empty table-empty">No unfrozen revisions match this search.</p>{/if}</section>
	</div><aside class="catalog-detail panel">
		{#if current()}<div class="detail-title"><div><p class="eyebrow">TRAINING-SET REVISION</p><h2>{familyName(current()!)}</h2><label>Revision<select value={selectedId} on:change={(event) => select(event.currentTarget.value)}>{#each versionEntries() as version}<option value={String(version.catalog_id)}>{display(version.training_set_version)} · {entryStatus(version)}</option>{/each}</select></label></div>{#if entryStatus(current()!) === 'frozen'}{#if onuse}<button on:click={() => onuse?.(current()!)}>Use for training</button>{/if}{:else}<button on:click={freeze} disabled={freezing}>{freezing ? 'Freezing…' : 'Freeze revision'}</button>{/if}</div>
			{#if loadingDetail}<p class="empty">Reading revision metadata…</p>{:else if detailError}<div class="preview-unavailable"><strong>Details unavailable</strong><p>{detailError}</p></div>{:else}<div class="catalog-facts"><div><span>Images</span><strong>{number(current()?.item_count).toLocaleString()}</strong></div><div><span>Classes</span><strong>{number(current()?.class_count).toLocaleString()}</strong></div><div><span>Lifecycle</span><strong>{entryStatus(current()!)}</strong></div></div><section><h3>Class balance</h3>{#if classes().length}<div class="class-list">{#each classes() as item}<button class:chosen={label === String(item.name)} on:click={() => setLabel(label === String(item.name) ? '' : String(item.name))}><span>{display(item.name)}</span><strong>{number(item.item_count).toLocaleString()}</strong></button>{/each}</div>{:else}<p class="empty">This revision has no classification labels.</p>{/if}</section><section><h3>Sample browser</h3>{#if previews.length}<div class="catalog-samples">{#each previews as sample}<article><img src={previewUrl(sample)} alt={`Sample ${display(sample.label ?? sample.source_key)}`} loading="lazy" /><small>{display(sample.label ?? sample.source_key)}</small></article>{/each}</div><div class="pager"><button class="secondary small" disabled={page === 0} on:click={() => movePage(-1)}>Previous</button><span>Page {page + 1}</span><button class="secondary small" disabled={previews.length < 18} on:click={() => movePage(1)}>Next</button></div>{:else}<p class="empty">This revision contains no previewable image assets.</p>{/if}</section><details><summary>Revision identity</summary><dl class="identity-grid"><div><dt>Dataset ID</dt><dd><code>{display(current()?.dataset_id)}</code></dd></div><div><dt>Revision ID</dt><dd><code>{display(asRecord(current()?.dataset_info).revision_id)}</code></dd></div><div><dt>Path</dt><dd>{display(current()?.path)}</dd></div></dl></details>{/if}
		{:else}<EmptyState title="Select a training-set revision" text="Choose a frozen or working revision to inspect its provenance and samples." />{/if}
	</aside></div>
{/if}

{#if comparison || comparisonError}<section class="comparison-panel panel"><div class="panel-head"><div><p class="eyebrow">REVISION COMPARISON</p><h2>Selected training-set revisions</h2></div><button class="quiet-button" on:click={() => { comparison = null; comparisonError = ''; }}>Close</button></div>{#if comparisonError}<p class="inline-error">{comparisonError}</p>{:else}<div class="comparison-grid">{#each asRecords(comparison?.entries) as entry}<article><h3>{display(entry.training_set_family ?? entry.name)}</h3><p>{display(entry.training_set_version)}</p><dl><div><dt>Images</dt><dd>{number(entry.item_count).toLocaleString()}</dd></div><div><dt>Classes</dt><dd>{number(entry.class_count).toLocaleString()}</dd></div><div><dt>Lifecycle</dt><dd>{display(entry.status)}</dd></div></dl></article>{/each}</div>{/if}</section>{/if}

<style>
	.catalog-intro,.detail-title,.catalog-toolbar,.catalog-row,.selection-actions,.panel-head,.catalog-table header{display:flex;align-items:center;gap:1rem}.catalog-intro{justify-content:space-between;margin:1.1rem 0}.catalog-intro p{max-width:46rem}.catalog-unavailable{padding:1rem;background:#fff8eb;border:1px solid #f0d8a6;border-radius:8px}.catalog-toolbar{padding:.8rem}.catalog-toolbar label{min-width:17rem}.selection-actions{margin-left:auto}.catalog-layout{display:grid;grid-template-columns:minmax(34rem,1.35fr) minmax(23rem,.85fr);gap:.75rem;align-items:start}.catalog-tables{display:grid;gap:.75rem}.catalog-table{margin:0;padding:0;overflow:hidden}.catalog-table header{justify-content:space-between;padding:.85rem 1rem;border-bottom:1px solid var(--line)}.catalog-table header h2{margin:0}.catalog-table header .eyebrow{margin:0 0 .2rem}.catalog-row{display:grid;grid-template-columns:2rem minmax(13rem,1fr) 4.5rem 6rem 4.5rem 5.5rem;padding:.62rem 1rem;border-bottom:1px solid var(--line);font-size:.78rem}.catalog-row.active{background:var(--teal-soft)}.catalog-head{background:#f8fafc;color:var(--muted);font-size:.64rem;font-weight:750;letter-spacing:.06em;text-transform:uppercase}.catalog-name{display:grid;justify-items:start;min-height:0;padding:0;color:var(--ink);background:transparent;text-align:left}.catalog-name:hover{color:var(--teal);background:transparent;transform:none}.catalog-name small{max-width:20rem;overflow:hidden;color:var(--muted);text-overflow:ellipsis;white-space:nowrap}.check{display:flex;align-items:center}.table-empty{padding:.8rem 1rem;margin:0}.catalog-detail{position:sticky;top:5.8rem;min-height:34rem;margin:0}.detail-title{align-items:flex-start;justify-content:space-between}.detail-title h2{margin:.1rem 0 .5rem}.detail-title label{min-width:13rem}.catalog-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:.45rem;margin:1rem 0}.catalog-facts div{padding:.65rem;background:#f8fafc;border:1px solid var(--line);border-radius:6px}.catalog-facts span,.catalog-facts strong{display:block}.catalog-facts span{color:var(--muted);font-size:.66rem;text-transform:uppercase}.catalog-facts strong{margin-top:.2rem;font-size:.9rem;text-transform:capitalize}.catalog-detail h3{margin:1rem 0 .45rem}.class-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.3rem;max-height:13rem;overflow:auto}.class-list button{display:flex;justify-content:space-between;min-height:2rem;padding:.35rem .45rem;color:var(--ink);background:#fff;border:1px solid var(--line);font-size:.72rem}.class-list button.chosen{color:var(--teal);background:var(--teal-soft);border-color:#93c5fd}.catalog-samples{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:.3rem}.catalog-samples article{overflow:hidden;background:#f1f5f9;border-radius:4px}.catalog-samples img{display:block;width:100%;aspect-ratio:1;height:auto;object-fit:cover}.catalog-samples small{display:none}.pager{display:flex;align-items:center;justify-content:center;gap:.5rem;margin-top:.55rem;font-size:.72rem}.comparison-panel{margin-top:.75rem}.comparison-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(13rem,1fr));gap:.65rem}.comparison-grid article{padding:.75rem;background:#f8fafc;border:1px solid var(--line);border-radius:6px}.comparison-grid h3,.comparison-grid p{margin:.1rem 0}.comparison-grid dl{margin:.5rem 0 0}.comparison-grid dl div{display:flex;justify-content:space-between;padding:.15rem 0}.comparison-grid dt{color:var(--muted)}.comparison-grid dd{margin:0}@media(max-width:960px){.catalog-layout{grid-template-columns:1fr}.catalog-detail{position:static}.catalog-row{grid-template-columns:2rem minmax(10rem,1fr) 4.5rem 5rem 4.5rem}.catalog-row>:last-child{display:none}}@media(max-width:620px){.catalog-intro,.detail-title{align-items:flex-start;flex-direction:column}.catalog-toolbar{align-items:stretch}.selection-actions{margin-left:0}.catalog-row{grid-template-columns:2rem 1fr 4rem}.catalog-row>:nth-child(4),.catalog-row>:nth-child(5){display:none}.catalog-facts{grid-template-columns:1fr}.catalog-samples{grid-template-columns:repeat(4,minmax(0,1fr))}}
</style>
